[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][string]$ManifestPath,
  [Parameter(Mandatory)][string]$ControlsReceiptPath,
  [Parameter(Mandatory)][string]$ReceiptPath
)
$ErrorActionPreference='Stop';$MaxJson=2MB;$MaxSource=64MB
function Require([bool]$ok,[string]$why){if(-not $ok){throw "r11 preflight rejected: $why"}}
function Read-BoundedJson([string]$path){$i=Get-Item -LiteralPath $path -Force;Require (-not $i.PSIsContainer -and (($i.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) -and $i.Length -le $MaxJson) "unsafe JSON $path";return [IO.File]::ReadAllText($i.FullName)|ConvertFrom-Json}
function Hash-Bounded([string]$path){$i=Get-Item -LiteralPath $path -Force;Require (-not $i.PSIsContainer -and (($i.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) -and $i.Length -le $MaxSource) "unsafe source $path";return [ordered]@{bytes=[int64]$i.Length;sha256=(Get-FileHash -LiteralPath $i.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function Parse-PowerShell([string]$path){$tokens=$null;$errors=$null;[void][Management.Automation.Language.Parser]::ParseFile($path,[ref]$tokens,[ref]$errors);Require ($errors.Count -eq 0) "PowerShell parse failed $path"}
$stage=[IO.Path]::GetFullPath($StageRoot);$plan=Read-BoundedJson $PlanPath;$manifest=Read-BoundedJson $ManifestPath;$controls=Read-BoundedJson $ControlsReceiptPath;$rows=Read-BoundedJson (Join-Path $stage 'source-input-rows.json')
Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run-r11') 'plan schema';Require ([string]$plan.status -eq 'source-pin-plan' -and [int]$plan.nativeActions -eq 0 -and [bool]$plan.qualificationClaim -eq $false) 'plan action/qualification flags';Require ([int64]$plan.aggregateJobMemoryLimitBytes -eq 1073741824 -and [string]$plan.memoryLimitFlags -eq '0x200' -and [int]$plan.deadlineSeconds -eq 900 -and [int]$plan.pollSeconds -eq 1) 'plan resource bounds';Require ([bool]$plan.noActivate -and [bool]$plan.noResources -and [int]$plan.runs -eq 1 -and [int]$plan.rows -eq 200 -and [int]$plan.keyRate -eq 10) 'plan workload guards';Require ([string]$manifest.schema -eq 'sr0-display-selfjob-v5-one-shot' -and [string]$manifest.candidateLineage -eq 'native-r10c-recovery-v1-r11') 'manifest lineage';Require ([bool]$manifest.noActivate -and [bool]$manifest.noResources -and [int64]$manifest.aggregateJobMemoryLimitBytes -eq 1073741824 -and [int]$manifest.deadlineSeconds -eq 900) 'manifest bounds';Require ([string]$controls.kind -eq 'sr0-display-workload-drain-controls-r10' -and [string]$controls.status -eq 'passed-source-controls' -and [bool]$controls.nativeQualificationClaim -eq $false) 'controls receipt status';Require (@($rows.rows).Count -eq 32) 'full source row count'
Require ([IO.Path]::GetFullPath([string]$plan.manifestPath) -ceq [IO.Path]::GetFullPath($ManifestPath) -and [IO.Path]::GetFullPath([string]$plan.sourceRowsPath) -ceq [IO.Path]::GetFullPath((Join-Path $stage 'source-input-rows.json'))) 'plan input paths do not match staged inputs'
Require ([string]$plan.sourcePins.collector -match '^[0-9a-fA-F]{64}$' -and [string]$plan.sourcePins.identityHelper -match '^[0-9a-fA-F]{64}$' -and [string]$plan.sourcePins.drainControlRunnerSha256 -match '^[0-9a-fA-F]{64}$') 'new collector/identity/control source pins missing'
Require ([string]$plan.workloadExeSha256 -eq [string]$manifest.workloadExeSha256 -and [string]$plan.rendererDllSha256 -eq [string]$manifest.rendererDllSha256 -and [string]$plan.presentMonSha256 -eq [string]$manifest.presentMonSha256) 'binary hash join missing'
$observed=@();foreach($row in @($rows.rows)){Require ([string]$row.name -match '^[A-Za-z][A-Za-z0-9]+$' -and [int64]$row.bytes -ge 0 -and [string]$row.sha256 -match '^[0-9a-fA-F]{64}$') 'source row shape';$p=if([bool]$row.external){[IO.Path]::GetFullPath([string]$row.path)}else{Require ([string]$row.path -notmatch '[\\:]') 'staged source path must be relative';Join-Path $stage ([string]$row.path)};$h=Hash-Bounded $p;Require ($h.bytes -eq [int64]$row.bytes -and $h.sha256 -ceq ([string]$row.sha256).ToLowerInvariant()) "source pin mismatch $($row.name)";if(([IO.Path]::GetExtension($p) -ieq '.ps1')){Parse-PowerShell $p};$observed+=$row}
Require ([int64]$rows.totalBytes -le 134217728) 'source total exceeds 128MiB';Require (@($rows.rows).Count -eq 32) 'full 32-row source closure required';$out=[ordered]@{kind='sr0-display-selfjob-r11-source-preflight';status='passed-source-preflight';stageRoot=$stage;planPath=[IO.Path]::GetFullPath($PlanPath);manifestPath=[IO.Path]::GetFullPath($ManifestPath);controlsReceiptPath=[IO.Path]::GetFullPath($ControlsReceiptPath);controlsReceiptSha256=(Get-FileHash -LiteralPath $ControlsReceiptPath -Algorithm SHA256).Hash.ToLowerInvariant();sourceCount=@($observed).Count;sourceRows=$observed;nativeQualificationClaim=$false;nativeActions=0;checkedAt=[DateTimeOffset]::UtcNow.ToString('o')}
if(Test-Path -LiteralPath $ReceiptPath){throw "fresh preflight receipt required: $ReceiptPath"};$parent=Split-Path -Parent ([IO.Path]::GetFullPath($ReceiptPath));if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$ReceiptPath.$PID.$([guid]::NewGuid().ToString('N')).tmp";[IO.File]::WriteAllText($tmp,(($out|ConvertTo-Json -Depth 12)+"`r`n"),[Text.Encoding]::UTF8);[IO.File]::Move($tmp,$ReceiptPath);Write-Output 'passed-source-preflight'
